export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const reason = String(inputs.reason === undefined || inputs.reason === null ? '' : inputs.reason);

  const TZ = 'Asia/Tashkent';
  const dateFmt = new Intl.DateTimeFormat('ru-RU', { timeZone: TZ, day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const fmt = (iso) => {
    if (!iso) return '';
    const s = /[Zz]$/.test(iso) || /[+-][0-9]{2}:?[0-9]{2}$/.test(iso) ? iso : iso + 'Z';
    const d = new Date(s);
    return isNaN(d.getTime()) ? '' : dateFmt.format(d);
  };

  const keyByReason = {
    not_found: 'event.card.not_found',
    event_cancelled: 'reg.event_cancelled',
    event_finished: 'reg.event_finished',
    not_published: 'reg.not_published',
    deadline_passed: 'reg.deadline_passed',
    no_seats: 'reg.no_seats'
  };
  const key = keyByReason[reason] || 'common.err.generic';
  const raw = String(texts[key] || key);
  const when = fmt(String(inputs.deadlineAt || ''));
  const text = raw.split('{when}').join(when);

  return { text: text, reason: reason };
};

export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const title = String(inputs.title === undefined || inputs.title === null ? '' : inputs.title);
  const raw = String(texts['reg.already'] || 'reg.already');
  const text = raw.split('{title}').join(title);
  return { text: text };
};

export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  // cardMessageId живёт в JSON внутри sessions.draft, а не отдельной колонкой:
  // схема таблиц заморожена с W1, а срок жизни поля равен сроку жизни сессии.
  const cardMessageId = Number(inputs.cardMessageId);
  const draft = {
    eventId: str(inputs.eventId),
    utm: str(inputs.utm),
    cardMessageId: isFinite(cardMessageId) && cardMessageId > 0 ? cardMessageId : 0
  };
  return { draft: JSON.stringify(draft), cardMessageId: draft.cardMessageId };
};

export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] || key);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };

  // Эталон экранирования MarkdownV2 — catalog/snippets/markdown-v2.md.
  // Экранируются все 18 символов из Bot API; обратный слэш первым, иначе
  // он удвоит уже добавленные слэши.
  const esc = (v) => String(v === undefined || v === null ? '' : v)
    .replace(/\\/g, '\\\\')
    .replace(/([_*\[\]()~`>#+\-=|{}.!])/g, '\\$1');

  const TZ = 'Asia/Tashkent';
  const dateFmt = new Intl.DateTimeFormat('ru-RU', { timeZone: TZ, day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const fmt = (iso) => {
    if (!iso) return '';
    const s = /[Zz]$/.test(iso) || /[+-][0-9]{2}:?[0-9]{2}$/.test(iso) ? iso : iso + 'Z';
    const d = new Date(s);
    return isNaN(d.getTime()) ? '' : dateFmt.format(d);
  };

  const str = (v) => String(v === undefined || v === null ? '' : v);
  const title = str(inputs.title);
  const description = str(inputs.description);
  const address = str(inputs.address);
  const startsAt = str(inputs.startsAt);
  const endsAt = str(inputs.endsAt);
  const regDeadlineAt = str(inputs.regDeadlineAt);

  const lat = Number(inputs.lat);
  const lon = Number(inputs.lon);
  const hasGeo = isFinite(lat) && isFinite(lon) && lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180;
  const mapsUrl = hasGeo ? ('https://yandex.uz/maps/?ll=' + lon + '%2C' + lat + '&z=17&pt=' + lon + '%2C' + lat) : '';

  // Карточка-экран: факты ивента и вопрос о согласии — одно сообщение,
  // которое дальше редактируется на месте (ADR-0017).
  const lines = [];
  if (title) lines.push('*' + esc(title) + '*');
  if (description) lines.push(esc(description));

  const facts = [];
  if (startsAt) facts.push('📅 ' + esc(fmt(startsAt)) + (endsAt ? ' — ' + esc(fmt(endsAt)) : ''));
  if (address) facts.push('📍 ' + esc(address));
  if (mapsUrl) facts.push('🗺 [Открыть на карте](' + mapsUrl + ')');
  if (regDeadlineAt) facts.push('⏳ ' + esc(t('event.card.deadline_short', { when: fmt(regDeadlineAt) })));
  if (facts.length) lines.push(facts.join('\n'));

  lines.push(esc(t('reg.consent_pdn.ask')));

  const replyMarkup = {
    inline_keyboard: [[
      { text: t('reg.consent_pdn.btn_yes'), callback_data: 'reg:pdn:yes' },
      { text: t('reg.consent_pdn.btn_no'), callback_data: 'reg:pdn:no' }
    ]]
  };

  return { text: lines.join('\n\n'), replyMarkup: replyMarkup, mapsUrl: mapsUrl, now: new Date().toISOString() };
};

